codeExamples.code:
-- 1. See the physical plan and whether Photon is used
EXPLAIN FORMATTED
SELECT user_id, count(*)
FROM events
WHERE event_date = '2026-06-19' AND country = 'US'
GROUP BY user_id;

-- 2. Collect table + column statistics for the cost-based optimizer
ANALYZE TABLE events COMPUTE STATISTICS FOR COLUMNS user_id, country, event_date;

-- 3. Cluster the table so data skipping works on the filter columns
ALTER TABLE events CLUSTER BY (event_date, country);
OPTIMIZE events;

-- 4. Inspect skipping effectiveness from the Delta history / metrics
DESCRIBE DETAIL events;
